import numpy as np
def equation(eps, T, params):
    a,b,c,d,e,f,p,g,k,h = params[:10]
    return (a+b*T+c*T**2) + (d+e*T+f*T**2)*eps**p + g*np.exp(-k*eps) + h*np.log(eps)
